package cards

import (
	"context"

	"github.com/jiva-studio/numen/libs/plugin-sdk-go/host/domain"
	"github.com/jiva-studio/numen/plugins/views-flashcards-studio/backend/note"
	"github.com/jiva-studio/numen/plugins/views-flashcards-studio/backend/ports"
)

// CardModelSummary is one card model as presented for choosing between them: the
// file path, the title, and the fields a card generated by it requires.
type CardModelSummary struct {
	Path   string
	Title  string
	Fields []string
}

// List lists every card model a vault holds.
//
// The index identifies which notes are card models and the files declare the
// fields of each, so a card model that cannot be read is listed with no fields.
type List struct {
	readers ports.VaultReaders
	notes   CardModelQueries
}

// CardModelQueries is the single index query that listing card models needs.
type CardModelQueries interface {
	// Card models is every card model one vault holds, by path. A card names the
	// card model it is cut by, and this is the list those names are picked from.
	GetCardModels(ctx context.Context, vaultID domain.VaultID) ([]ports.CardModel, error)
}

// NewList returns a List over the card models of a vault: the index query that
// identifies which notes are card models, and the readers that load each for its
// fields.
func NewList(readers ports.VaultReaders, notes CardModelQueries) List {
	return List{readers: readers, notes: notes}
}

// Execute lists the card models of one vault, by path, and reports how many the
// vault holds.
//
// Limit is how many of them are read, and zero or less reads all of them. The
// index reports the total, so the count is returned without opening a file for
// the card models beyond the limit.
func (u List) Execute(
	ctx context.Context, v domain.Vault, limit int,
) ([]CardModelSummary, int, error) {
	all, err := u.notes.GetCardModels(ctx, v.ID)
	if err != nil {
		return nil, 0, err
	}
	target := all
	if limit > 0 {
		target = all[:min(limit, len(all))]
	}

	// 	// A card model holds no cards, so no wikilink resolution is needed.
	read := NewRead(u.readers, nil)
	out := make([]CardModelSummary, 0, len(target))
	for _, s := range target {
		items := CardModelSummary{Path: s.Path, Title: s.Title, Fields: nil}
		cardModel, err := read.CardModel(ctx, v, s.Path)
		if err != nil {
			return nil, 0, err
		}
		if cardModel.Outcome == note.Ok {
			items.Fields = cardModel.Body.Fields
		}
		out = append(out, items)
	}
	return out, len(all), nil
}
